\begin{definition}[Garbling scheme for oracle-aided circuits relative to $f$]\label{def:garb}
Fix a function $f$. A triple of algorithms $L=(\mathsf{Garb},\mathsf{Eval},\mathsf{Sim})$ is a \emph{garbling scheme for oracle-aided circuits relative to $f$} (equivalently, \emph{with $f$-gates}) if:
\begin{itemize}
\item $\mathsf{Garb}(1^{\kappa},\mathsf{C})$ takes the security parameter and a binary-output oracle-aided circuit $\mathsf{C}$ with $m=\mathsf{inpsize}(\mathsf{C})$, and outputs a garbled circuit $\widetilde{\mathsf{C}}$ together with a set of labels $\{\mathsf{label}_{i,b}\}_{i\in[m],b\in\{0,1\}}$;
\item $\mathsf{Eval}^{f}\big(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,b_i}\}_{i\in[m]}\big)$ takes a garbled circuit and a garbled input and outputs a value in $\{0,1\}^{*}\cup\{\bot\}$;
\item \textbf{Correctness.} For every binary-output oracle-aided circuit $\mathsf{C}$ with $m=\mathsf{inpsize}(\mathsf{C})$ and every $x\in\{0,1\}^{m}$,
$\Pr\big[\mathsf{C}^{f}(x)=\mathsf{Eval}^{f}(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,x_i}\}_{i\in[m]})\big]=1$, the probability being over $(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,b}\}_{i\in[m],b\in\{0,1\}})\leftarrow\mathsf{Garb}(1^{\kappa},\mathsf{C})$;
\item \textbf{Security.} For every polynomial $m=m(\kappa)$, every poly-size binary-output oracle-aided circuit $\mathsf{C}$ with $\mathsf{inpsize}(\mathsf{C})=m$ and every $x\in\{0,1\}^{m}$,
$\big(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,x_i}\}_{i\in[m]}\big)\stackrel{c}{\approx}\mathsf{Sim}\big(1^{|\mathsf{C}|},m,\mathsf{C}^{f}(x)\big)$, where $(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,b}\}_{i\in[m],b\in\{0,1\}})\leftarrow\mathsf{Garb}(1^{\kappa},\mathsf{C})$.
\end{itemize}
The labels are per input \emph{bit} (``projective'' or ``decomposable'' garbling): a garbled input for a string is assembled wire by wire out of independently chosen labels. A scheme is \emph{correct} if it satisfies the correctness clause. The pair consisting of a one-way function $f$ and such a scheme $L$ is the primitive \textup{GC-OWF}.
\end{definition}

\begin{definition}[Key-agreement protocol]\label{def:ka}
For $m\in\mathbb{N}$, a \emph{$2m$-round key-agreement protocol} is a pair of PPT interactive algorithms $(A,B)$ such that $\langle A(r_a),B(r_b)\rangle(1^{\kappa})=(k_a,k_b)$ for private randomness $r_a,r_b$; write $k:=k_a$.
\begin{itemize}
\item \textbf{Correctness.} For a function $\delta(\cdot)$ the protocol is \emph{$(1-\delta)$-correct} if $\Pr[k_a=k_b]\ge 1-\delta(\kappa)$ for every $\kappa$, the probability being over the randomness of $A$ and $B$. It is \emph{correct} if it is $(1-\delta)$-correct with $\delta(\kappa)=1/p(\kappa)$ for some polynomial $p$.
\item \textbf{Security.} For a function $\gamma(\cdot)$ the protocol is \emph{$\gamma$-secure} if for every PPT adversary $E$ and every $\kappa$, $\Pr[E(1^{\kappa},\mathsf{Tr})=k]\le\gamma(\kappa)$, where $\mathsf{Tr}\leftarrow\mathsf{Trans}\langle A(r_a),B(r_b)\rangle$ and the probability is over the randomness of $E$, $A$ and $B$. It is \emph{secure} if it is $\gamma$-secure for some $\gamma(\kappa)=\mathrm{negl}(\kappa)$. An adversary $E$ \emph{breaks} the protocol if $\Pr[E(1^{\kappa},\mathsf{Tr})=k]$ is non-negligible in $\kappa$.
\end{itemize}
\end{definition}

\begin{definition}[Fully black-box construction of key agreement from GC-OWF]\label{def:bb}
A \emph{fully black-box construction of a key-agreement protocol from \textup{GC-OWF}} consists of a pair of oracle PPT interactive algorithms $(A,B)$ together with an oracle PPT security reduction $S=(S_1,S_2)$, such that for every function $f$ and every correct garbling scheme $L=(\mathsf{Garb},\mathsf{Eval},\mathsf{Sim})$ for oracle-aided circuits relative to $f$ (Definition~\ref{def:garb}) both of the following hold.
\begin{itemize}
\item \textbf{Correctness.} $\langle A^{f,L},B^{f,L}\rangle$ is a correct key-agreement protocol in the sense of Definition~\ref{def:ka}.
\item \textbf{Security.} For every adversary $E$ that breaks $\langle A^{f,L},B^{f,L}\rangle$, either
\begin{itemize}
\item $S_1^{f,L,E}$ breaks the one-wayness of $f$; or
\item $S_2^{f,L,E}$ breaks the security of $L$ relative to $f$: for some binary-output oracle-aided circuit $\mathsf{C}$ with $m=\mathsf{inpsize}(\mathsf{C})$ and some $x\in\{0,1\}^{m}$, the algorithm $S_2^{f,L,E}$ distinguishes $\big(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,x_i}\}_{i\in[m]}\big)$ from $\mathsf{Sim}\big(1^{|\mathsf{C}|},1^{|x|},\mathsf{C}^{f}(x)\big)$ with non-negligible advantage, where $(\widetilde{\mathsf{C}},\{\mathsf{label}_{i,b}\}_{i\in[m],b\in\{0,1\}})\leftarrow\mathsf{Garb}(1^{\kappa},\mathsf{C})$.
\end{itemize}
\end{itemize}
The round complexity of $\langle A,B\rangle$ is whatever $(A,B)$ prescribe. Since $A$ and $B$ are PPT it is bounded by a polynomial in $\kappa$; it is \emph{not} required to be bounded by a constant.
\end{definition}
